sealed class VimivoFfiException: kotlin.Exception() {
    
    class DatabaseException(
        
        val `reason`: kotlin.String
        ) : VimivoFfiException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    
    class NotFound(
        
        val `reason`: kotlin.String
        ) : VimivoFfiException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    
    class InternalException(
        
        val `reason`: kotlin.String
        ) : VimivoFfiException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<VimivoFfiException> {
        override fun lift(error_buf: RustBuffer.ByValue): VimivoFfiException = FfiConverterTypeVimivoFfiError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeVimivoFfiError : FfiConverterRustBuffer<VimivoFfiException> {
    override fun read(buf: ByteBuffer): VimivoFfiException {
        

        return when(buf.getInt()) {
            1 -> VimivoFfiException.DatabaseException(
                FfiConverterString.read(buf),
                )
            2 -> VimivoFfiException.NotFound(
                FfiConverterString.read(buf),
                )
            3 -> VimivoFfiException.InternalException(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: VimivoFfiException): ULong {
        return when(value) {
            is VimivoFfiException.DatabaseException -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
            )
            is VimivoFfiException.NotFound -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
            )
            is VimivoFfiException.InternalException -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
            )
        }
    }

    override fun write(value: VimivoFfiException, buf: ByteBuffer) {
        when(value) {
            is VimivoFfiException.DatabaseException -> {
                buf.putInt(1)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
            is VimivoFfiException.NotFound -> {
                buf.putInt(2)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
            is VimivoFfiException.InternalException -> {
                buf.putInt(3)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}




